--
-- Table structure for table `astc_vote`
--

CREATE TABLE `astc_vote` (
  `ID` int(11) NOT NULL,
  `name` varchar(100) NOT NULL,
  `company` varchar(200) NOT NULL,
  `img` varchar(100) NOT NULL,
  `kid` varchar(1) NOT NULL COMMENT '1 = 總會長， 2 = 監事長， 3 = 各國',
  `position` varchar(1) NOT NULL DEFAULT '0' COMMENT '1 = 總會長， 2 = 監事長',
  `vote_hueizhang_permission` int(3) NOT NULL DEFAULT 0 COMMENT '會長有權投票人數',
  `vote_hueizhang_agree` int(10) NOT NULL DEFAULT 0 COMMENT '會長同意票數',
  `vote_hueizhang_anti` int(10) NOT NULL DEFAULT 0 COMMENT '會長不同意票數',
  `vote_jianshi_permission` int(3) NOT NULL DEFAULT 0,
  `vote_jianshi_agree` int(3) NOT NULL DEFAULT 0 COMMENT '監事同意票數',
  `vote_jianshi_anti` int(3) NOT NULL DEFAULT 0 COMMENT '監事不同意票數',
  `vote_fail` int(10) NOT NULL DEFAULT 0 COMMENT '廢票數',
  `vote_total` int(10) NOT NULL,
  `status` varchar(1) NOT NULL DEFAULT '1' COMMENT '1 = true; 0= false',
  `create_date` varchar(10) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

