(4680, 7, '2023-08-04 13:10:03', '2023-08-04 05:10:03', '\n/* 相片頁面CSS */\n.container01{\n        width: 1400px;\n        margin: 20px auto;\n        columns: 3;\n        column-gap: 20px;\n    }\n\n    .container01 .imgbox{\n        width: 100%;\n        margin-bottom: 10px;\n        break-inside: avoid;\n    }\n\n    .container01 .imgbox img{\n        max-width: 100%;\n        border-radius: 15px;\n    }\n\n    @media (max-width: 1200px){\n        .container01{\n            width: calc(100% - 40px);\n            columns: 3;\n        }\n    }\n\n    @media (max-width: 768px){\n        .container01{\n            columns: 2;\n        }\n    }\n\n    @media (max-width: 480px){\n        .container01{\n            columns: 1;\n        }\n    }', '2020', '', 'inherit', 'closed', 'closed', '', '4622-revision-v1', '', '', '2023-08-04 13:10:03', '2023-08-04 05:10:03', '', 4622, 'http://localhost/astcc/4622-revision-v1/', 0, 'revision', '', 0),
