(4699, 7, '2023-08-07 15:49:09', '2023-08-07 07:49:09', ' /* 相片標題頁面 */\n    .container-all{\n        width: calc(100% - 40px);\n        padding: 0 3%;\n        margin: 20px auto;\n        columns: 3;\n        column-gap: 40px;\n        max-width: 1500px;\n        \n    }\n\n\n    .container-all .titlebox{\n        width: 100%;\n        margin-bottom: 10px;\n        break-inside: avoid;\n        text-decoration:none;\n    }\n\n    .container-all .titlebox img{\n        width: 100%;\n        border-top-left-radius: 15px;\n        border-top-right-radius: 15px;\n        height: 320px;\n        object-fit: cover;\n    }\n\n    .container-all .titlebox h2{\n        font-size: 22px;\n        color: #fff;\n        background-color: #286090;\n        padding: 10px;\n        border-bottom-left-radius: 15px;\n        border-bottom-right-radius: 15px;\n        margin-top: -5px;\n        \n    }\n\n\n\n/* 相片頁面CSS */\n.container01{\n        width: 1400px;\n        margin: 20px auto;\n        columns: 3;\n        column-gap: 20px;\n    }\n\n    .container01 .imgbox{\n        width: 100%;\n        margin-bottom: 10px;\n        break-inside: avoid;\n			  overflow:hidden;\n    }\n\n    .container01 .imgbox img{\n        max-width: 100%;\n        border-radius: 15px;\n			  transition: 0.5s;\n    }\n.container01 .imgbox img:hover{\n        transform: scale(1.2);\n    }\n\n    @media (max-width: 1200px){\n        .container01{\n            width: calc(100% - 40px);\n            columns: 3;\n        }\n    }\n\n    @media (max-width: 768px){\n        .container01{\n            columns: 2;\n        }\n    }\n\n    @media (max-width: 480px){\n        .container01{\n            columns: 1;\n        }\n    }', '2020', '', 'inherit', 'closed', 'closed', '', '4622-revision-v1', '', '', '2023-08-07 15:49:09', '2023-08-07 07:49:09', '', 4622, 'http://localhost/astcc/4622-revision-v1/', 0, 'revision', '', 0),
